fn valid_request_id(value: &Value) -> bool {
    match value {
        Value::String(id) => {
            !id.is_empty() && id.len() <= 128 && id.bytes().all(|byte| byte.is_ascii_graphic())
        }
        _ => false,
    }
}

fn oversized_frame_response() -> Value {
    serde_json::to_value(Response::error(
        Value::Null,
        -32005,
        "AAP frame exceeds the negotiated limit",
    ))
    .expect("frame limit response serialization")
}

fn parse_protocol_version(value: &str) -> Option<(u64, u64)> {
    if value.len() > 16 {
        return None;
    }
    let (major, minor) = value.split_once('.')?;
    if major.is_empty()
        || minor.is_empty()
        || (major.len() > 1 && major.starts_with('0'))
        || (minor.len() > 1 && minor.starts_with('0'))
        || !major.bytes().all(|byte| byte.is_ascii_digit())
        || !minor.bytes().all(|byte| byte.is_ascii_digit())
    {
        return None;
    }
    Some((major.parse().ok()?, minor.parse().ok()?))
}

fn valid_identity_name(value: &str) -> bool {
    let mut needs_segment = true;
    for byte in value.bytes() {
        if byte.is_ascii_lowercase() || byte.is_ascii_digit() {
            needs_segment = false;
        } else if matches!(byte, b'.' | b'-') && !needs_segment {
            needs_segment = true;
        } else {
            return false;
        }
    }
    !value.is_empty() && value.len() <= 64 && !needs_segment
}

fn valid_identity_version(value: &str) -> bool {
    !value.is_empty() && value.len() <= 64 && value.bytes().all(|byte| byte.is_ascii_graphic())
}

fn runtime_platform() -> Platform {
    let os = match std::env::consts::OS {
        "macos" => "macos",
        "windows" => "windows",
        "linux" => "linux",
        _ => "unknown",
    };
    let architecture = match std::env::consts::ARCH {
        "aarch64" => "arm64",
        "x86_64" => "x86_64",
        _ => "unknown",
    };
    Platform {
        os: os.into(),
        architecture: architecture.into(),
    }
}

struct RuntimeTimelineSubscriptionContext {
    subscribe_result: TimelineSubscribeResult,
    fixed_floor: public_timeline_journal::TimelineAnchor,
    fixed_head: public_timeline_journal::TimelineAnchor,
    activation_token: Option<timeline_subscription::TimelineSubscriptionActivationToken>,
    active_result: Option<TimelineActivateResult>,
}

#[derive(Default)]
struct RuntimeTimelineSubscriptionState {
    registry: Option<timeline_subscription::TimelineSubscriptionRegistry>,
    contexts: HashMap<String, RuntimeTimelineSubscriptionContext>,
    sessions: HashMap<String, String>,
}

impl RuntimeTimelineSubscriptionState {
    fn retire(&mut self, subscription_id: &str) {
        if let Some(context) = self.contexts.remove(subscription_id) {
            self.sessions.remove(&context.subscribe_result.session_id);
        }
        if let Some(registry) = self.registry.as_mut() {
            let _ = registry.retire(subscription_id);
        }
    }

    fn disconnect(&mut self) {
        if let Some(registry) = self.registry.take() {
            let _ = registry.disconnect();
        }
        self.contexts.clear();
        self.sessions.clear();
    }
}

