#[cfg(test)]
mod capability_matrix_integration_tests {
    use super::{test_initialize_params, Runtime};
    use serde_json::{json, Value};

    fn call(runtime: &mut Runtime, id: &str, method: &str) -> Vec<Value> {
        runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": id,
                "method": method,
                "params": if method == "initialize" {
                    test_initialize_params("capability-test")
                } else {
                    json!({})
                }
            })
            .to_string(),
        )
    }

    #[test]
    fn unavailable_initialize_and_degradation_snapshot_do_not_claim_provider_reachability() {
        let mut runtime = Runtime::unavailable("sensitive startup detail");
        let initialized = call(&mut runtime, "initialize", "initialize");
        assert_eq!(
            initialized[0]["result"]["backend"]["adapter"],
            "codex-app-server"
        );
        assert_eq!(
            initialized[0]["result"]["backend"]["version"],
            "codex-cli 0.144.5"
        );
        let capabilities = initialized[0]["result"]["capabilities"]["stable"]
            .as_array()
            .unwrap();
        assert!(!capabilities.iter().any(|capability| {
            capability
                .as_str()
                .is_some_and(|value| value.starts_with("timeline.") || value.contains("provider"))
        }));
        assert!(runtime
            .handle_line(r#"{"jsonrpc":"2.0","method":"initialized","params":{}}"#)
            .is_empty());

        let response = call(&mut runtime, "degradations", "runtime/degradations");
        let snapshot = &response[0]["result"];
        assert_eq!(snapshot["schema_version"], "runtime-degradations/0.2");
        assert_eq!(snapshot["backend"]["kind"], "unavailable");
        assert_eq!(snapshot["backend"]["version"], "codex-cli 0.144.5");
        assert_eq!(
            snapshot["capability_matrix"]["identity"],
            "codex-capability-matrix:sha256:473ddd66cd30b903778c248f28aa55d3cfb2ff37123c4831a23a263703362d04"
        );
        assert_eq!(snapshot["complete"], true);
        assert_eq!(snapshot["degradations"].as_array().unwrap().len(), 4);
        assert!(snapshot["degradations"]
            .as_array()
            .unwrap()
            .iter()
            .all(|feature| feature["scope"] != "provider"
                && !feature["feature"]
                    .as_str()
                    .unwrap()
                    .starts_with("timeline.")));
        assert!(!serde_json::to_string(snapshot)
            .unwrap()
            .contains("sensitive startup detail"));
    }
}

#[cfg(test)]
mod emergency_workbench_tests {
    use super::{test_initialize_params, Runtime};
    use serde_json::json;
    use std::fs;
    use std::path::PathBuf;
    use std::time::{SystemTime, UNIX_EPOCH};

    struct TestRoot(PathBuf);

    impl TestRoot {
        fn new() -> Self {
            let unique = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos();
            let path = std::env::temp_dir().join(format!(
                "aegisy-emergency-workbench-{}-{unique}",
                std::process::id()
            ));
            fs::create_dir_all(&path).unwrap();
            Self(path)
        }
    }

    impl Drop for TestRoot {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn emergency_store_starts_without_codex_and_keeps_history_export_read_only() {
        let root = TestRoot::new();
        let source_session_id = {
            let mut writable = Runtime::with_store(&root.0).unwrap();
            let initialize = writable.handle_line(
                &json!({
                    "jsonrpc": "2.0",
                    "id": "warm-init",
                    "method": "initialize",
                    "params": test_initialize_params("emergency-warm-store")
                })
                .to_string(),
            );
            assert!(initialize[0].get("result").is_some());
            assert!(writable
                .handle_line(r#"{"jsonrpc":"2.0","method":"initialized","params":{}}"#)
                .is_empty());
            let started = writable.handle_line(
                r#"{"jsonrpc":"2.0","id":"warm-start","method":"session/start","params":{"mode":"chat","title":"Emergency export fixture"}}"#,
            );
            started[0]["result"]["session"]["id"]
                .as_str()
                .unwrap()
                .to_owned()
        };

        let mut runtime = Runtime::with_emergency_store(&root.0).unwrap();
        let initialize = runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": "init",
                "method": "initialize",
                "params": test_initialize_params("emergency-test")
            })
            .to_string(),
        );
        assert_eq!(initialize[0]["result"]["backend"]["adapter"], "preview");
        let capabilities = initialize[0]["result"]["capabilities"]["stable"]
            .as_array()
            .unwrap();
        let has = |name: &str| capabilities.iter().any(|value| value == name);
        assert!(has("session.list"));
        assert!(has("session.history.paginated"));
        assert!(has("session.portable.export"));
        assert!(has("runtime.projection-recovery.status"));
        assert!(!has("session.chat"));
        assert!(!has("session.work.preview"));
        assert!(!has("workspace.save-user-text"));
        assert!(!has("terminal.lifecycle.named"));
        assert!(runtime
            .handle_line(r#"{"jsonrpc":"2.0","method":"initialized","params":{}}"#)
            .is_empty());

        let projects = runtime.handle_line(
            r#"{"jsonrpc":"2.0","id":"projects","method":"project/list","params":{"limit":10}}"#,
        );
        assert!(projects[0].get("result").is_some());

        let history = runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": "history",
                "method": "session/read",
                "params": {"session_id": &source_session_id}
            })
            .to_string(),
        );
        assert_eq!(history[0]["result"]["session"]["id"], source_session_id);

        let export_preview = runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": "export-preview",
                "method": "session/export/preview",
                "params": {"session_id": &source_session_id}
            })
            .to_string(),
        );
        assert_eq!(
            export_preview[0]["result"]["schema_version"],
            "portable-session-export-preview/0.1"
        );
        let export = runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": "export",
                "method": "session/export",
                "params": {
                    "session_id": &source_session_id,
                    "package_hash": export_preview[0]["result"]["package_hash"].clone()
                }
            })
            .to_string(),
        );
        assert_eq!(
            export[0]["result"]["schema_version"],
            "portable-session-export-result/0.1"
        );

        for (id, method, params) in [
            ("start", "session/start", json!({"mode":"chat"})),
            (
                "turn",
                "turn/start",
                json!({"session_id":"session-1","input":"x"}),
            ),
            (
                "save",
                "workspace/save-user-text",
                json!({"project_id":"project-1","path":"a.txt","content":"x"}),
            ),
            ("import", "session/import", json!({"package": {}})),
            ("restart", "runtime/restart", json!({})),
        ] {
            let response = runtime.handle_line(
                &json!({
                    "jsonrpc": "2.0",
                    "id": id,
                    "method": method,
                    "params": params
                })
                .to_string(),
            );
            assert_eq!(response[0]["error"]["code"], -32153, "{method}");
        }
    }

    #[test]
    fn emergency_without_a_data_root_never_starts_codex() {
        let mut runtime = Runtime::emergency();
        let initialize = runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": "init",
                "method": "initialize",
                "params": test_initialize_params("emergency-no-store")
            })
            .to_string(),
        );
        assert_eq!(initialize[0]["result"]["backend"]["status"], "unavailable");
        assert_ne!(
            initialize[0]["result"]["backend"]["adapter"],
            "codex-app-server"
        );
    }

    #[test]
    fn emergency_store_recovery_keeps_the_central_mutation_gate() {
        let root = TestRoot::new();
        fs::write(
            root.0.join("aegisy-workbench.sqlite3"),
            b"not a sqlite database",
        )
        .unwrap();

        let mut runtime = Runtime::with_emergency_store(&root.0).unwrap();
        let initialize = runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": "init",
                "method": "initialize",
                "params": test_initialize_params("emergency-recovery")
            })
            .to_string(),
        );
        assert_eq!(
            initialize[0]["result"]["backend"]["status"],
            "read-only-recovery"
        );
        assert_ne!(
            initialize[0]["result"]["backend"]["adapter"],
            "codex-app-server"
        );
        assert!(runtime
            .handle_line(r#"{"jsonrpc":"2.0","method":"initialized","params":{}}"#)
            .is_empty());

        let blocked = runtime.handle_line(
            r#"{"jsonrpc":"2.0","id":"start","method":"session/start","params":{"mode":"chat"}}"#,
        );
        assert_eq!(blocked[0]["error"]["code"], -32153);
    }
}

#[cfg(test)]
mod provider_thread_projection_tests {
    use super::{provider_optional_opaque_text, provider_thread_summary, provider_turn_summaries};
    use serde_json::json;

    #[test]
    fn provider_thread_projection_omits_dynamic_content_and_paths() {
        let secret = "sk-provider-thread-private";
        let thread = json!({
            "id": "thread-1",
            "sessionId": "session-private",
            "name": format!("Private title {secret}"),
            "preview": format!("Private preview {secret}"),
            "cwd": "/private/workspace/source",
            "path": "/private/provider/rollout.jsonl",
            "modelProvider": "private-provider-name",
            "source": {"custom": format!("private-source-{secret}")},
            "status": {
                "type": "active",
                "activeFlags": ["waitingOnApproval", "private-dynamic-flag"]
            },
            "createdAt": 10,
            "updatedAt": 20,
            "recencyAt": 21,
            "ephemeral": false,
            "forkedFromId": "private-parent-thread",
            "turns": [{
                "id": "turn-1",
                "status": "completed",
                "startedAt": 10,
                "completedAt": 20,
                "durationMs": 10,
                "items": [{"type": "userMessage", "content": secret}],
                "error": null
            }]
        });

        let summary = provider_thread_summary(&thread).unwrap();
        assert_eq!(summary["thread_id"], "thread-1");
        assert_eq!(summary["source_kind"], "custom");
        assert_eq!(summary["status"]["state"], "active");
        assert_eq!(summary["status"]["waiting_on_approval"], true);
        assert_eq!(summary["name_present"], true);
        assert_eq!(summary["preview_present"], true);
        assert_eq!(summary["path_present"], true);
        assert_eq!(summary["turn_count"], 1);
        assert_eq!(summary["content_omitted"], true);
        assert!(summary["workspace_identity"]
            .as_str()
            .unwrap()
            .starts_with("sha256:"));
        let turns = provider_turn_summaries(&thread).unwrap();
        assert_eq!(turns[0]["turn_id"], "turn-1");
        assert_eq!(turns[0]["status"], "completed");
        assert_eq!(turns[0]["item_count"], 1);
        assert_eq!(turns[0]["content_omitted"], true);

        let encoded = serde_json::to_string(&(summary, turns)).unwrap();
        for forbidden in [
            secret,
            "Private title",
            "Private preview",
            "/private/workspace/source",
            "/private/provider/rollout.jsonl",
            "private-provider-name",
            "private-source",
            "private-dynamic-flag",
            "private-parent-thread",
            "userMessage",
        ] {
            assert!(
                !encoded.contains(forbidden),
                "projection leaked {forbidden}"
            );
        }
    }

    #[test]
    fn provider_cursor_projection_is_lossless_or_fails_closed() {
        let ordinary_cursor = json!("opaque:provider:cursor:1");
        assert_eq!(
            provider_optional_opaque_text(
                Some(&ordinary_cursor),
                "Codex thread/list nextCursor",
                4 * 1024,
            )
            .unwrap()
            .as_deref(),
            Some("opaque:provider:cursor:1")
        );

        for invalid in [
            json!("opaque-cursor Authorization: Bearer ghp_123456789012345678901234567890"),
            json!("opaque\ncursor"),
            json!("x".repeat(4 * 1024 + 1)),
        ] {
            assert!(provider_optional_opaque_text(
                Some(&invalid),
                "Codex thread/list nextCursor",
                4 * 1024,
            )
            .is_err());
        }
        assert_eq!(
            provider_optional_opaque_text(None, "Codex thread/list nextCursor", 4 * 1024).unwrap(),
            None
        );
        assert_eq!(
            provider_optional_opaque_text(
                Some(&serde_json::Value::Null),
                "Codex thread/list nextCursor",
                4 * 1024,
            )
            .unwrap(),
            None
        );
    }

    #[test]
    fn provider_turn_ids_are_exact_or_the_complete_projection_is_rejected() {
        let prefix = "t".repeat(256);
        let colliding_if_truncated = json!({
            "turns": [
                {"id": format!("{prefix}a"), "status": "completed", "items": []},
                {"id": format!("{prefix}b"), "status": "completed", "items": []}
            ]
        });
        assert!(provider_turn_summaries(&colliding_if_truncated).is_err());

        for invalid_id in [
            "turn\ncontrol".to_owned(),
            "Authorization: Bearer ghp_123456789012345678901234567890".to_owned(),
        ] {
            let thread = json!({
                "turns": [{"id": invalid_id, "status": "completed", "items": []}]
            });
            assert!(provider_turn_summaries(&thread).is_err());
        }
    }
}

#[derive(Clone, Default)]
pub struct RuntimeControl {
    state: Arc<Mutex<RuntimeControlState>>,
    terminals: Arc<Mutex<TerminalState>>,
}

#[derive(Clone, Debug)]
pub struct DecodedRequestFrame {
    request: Request,
    message: TransportMessage,
    kind: TransportRequestOrNotificationKind,
    definition_validator: DefinitionValidator,
    byte_len: usize,
}

type DefinitionValidator =
    fn(&TransportMessage, TransportRequestOrNotificationKind) -> Result<(), TransportDispatchError>;
type GenericValidator = fn(&TransportMessage) -> Result<(), TransportDispatchError>;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RequestFrameError {
    Parse(aegisy_aap::transport_json::TransportJsonError),
    InvalidEnvelope { response_id: Option<Value> },
    ValidatorUnavailable,
}

impl DecodedRequestFrame {
    pub fn request(&self) -> &Request {
        &self.request
    }

    pub fn kind(&self) -> TransportRequestOrNotificationKind {
        self.kind
    }

    pub fn byte_len(&self) -> usize {
        self.byte_len
    }

    fn prove_definition_validator_available(&self) -> Result<(), RequestFrameError> {
        match (self.definition_validator)(&self.message, self.kind) {
            Ok(()) | Err(TransportDispatchError::InvalidKnownMessage) => Ok(()),
            Err(_) => Err(RequestFrameError::ValidatorUnavailable),
        }
    }

    fn validate_known_kind(&self) -> Result<(), TransportDispatchError> {
        validate_transport_request_or_notification_kind(&self.message, self.kind)
    }
}

fn invalid_envelope_response_id(message: &TransportMessage) -> Option<Value> {
    let object = message.0.as_object()?;
    match object.get("id") {
        Some(id) if valid_request_id(id) => Some(id.clone()),
        Some(_) => Some(Value::Null),
        None => None,
    }
}

pub fn decode_request_frame(bytes: &[u8]) -> Result<DecodedRequestFrame, RequestFrameError> {
    decode_request_frame_with_validators(
        bytes,
        validate_transport_generic_message,
        validate_transport_request_or_notification_definition,
    )
}

fn decode_request_frame_with_validators(
    bytes: &[u8],
    generic_validator: GenericValidator,
    definition_validator: DefinitionValidator,
) -> Result<DecodedRequestFrame, RequestFrameError> {
    let message = parse_transport_message_raw(bytes).map_err(|error| match error {
        TransportDecodeError::Parse(error) => RequestFrameError::Parse(error),
        _ => RequestFrameError::ValidatorUnavailable,
    })?;
    generic_validator(&message).map_err(|error| match error {
        TransportDispatchError::InvalidEnvelope => RequestFrameError::InvalidEnvelope {
            response_id: invalid_envelope_response_id(&message),
        },
        TransportDispatchError::ValidatorUnavailable => RequestFrameError::ValidatorUnavailable,
        _ => RequestFrameError::ValidatorUnavailable,
    })?;
    let kind =
        classify_transport_request_or_notification(&message).map_err(|error| match error {
            TransportDispatchError::Parse(_) | TransportDispatchError::InvalidEnvelope => {
                RequestFrameError::InvalidEnvelope {
                    response_id: invalid_envelope_response_id(&message),
                }
            }
            TransportDispatchError::ValidatorUnavailable => RequestFrameError::ValidatorUnavailable,
            TransportDispatchError::InvalidKnownMessage => RequestFrameError::ValidatorUnavailable,
            _ => RequestFrameError::ValidatorUnavailable,
        })?;
    let object = message
        .0
        .as_object()
        .expect("validated request or notification envelope is an object");
    let request = Request {
        jsonrpc: object
            .get("jsonrpc")
            .and_then(Value::as_str)
            .expect("validated envelope has JSON-RPC version")
            .to_owned(),
        id: object.get("id").cloned(),
        method: object
            .get("method")
            .and_then(Value::as_str)
            .expect("validated request or notification has method")
            .to_owned(),
        params: object
            .get("params")
            .cloned()
            .expect("validated request or notification has params"),
    };
    Ok(DecodedRequestFrame {
        request,
        message,
        kind,
        definition_validator,
        byte_len: bytes.len(),
    })
}

pub fn request_frame_error_response(error: &RequestFrameError) -> Option<Value> {
    let (id, code, message) = match error {
        RequestFrameError::Parse(_) => (Value::Null, -32700, "parse error"),
        RequestFrameError::InvalidEnvelope {
            response_id: Some(id),
        } => (id.clone(), -32600, "invalid JSON-RPC request envelope"),
        RequestFrameError::InvalidEnvelope { response_id: None } => return None,
        RequestFrameError::ValidatorUnavailable => return None,
    };
    Some(
        serde_json::to_value(Response::error(id, code, message))
            .expect("request frame error response serialization"),
    )
}

#[cfg(test)]
mod generated_transport_ingress_failure_tests {
    use super::{
        decode_request_frame, decode_request_frame_with_validators, request_frame_error_response,
        test_initialize_params, RequestFrameError, Runtime, RuntimeControl, TransportDispatchError,
        TransportMessage, TransportRequestOrNotificationKind,
    };
    use serde_json::{json, Value};

    fn validator_unavailable(
        _message: &TransportMessage,
        _kind: TransportRequestOrNotificationKind,
    ) -> Result<(), TransportDispatchError> {
        Err(TransportDispatchError::ValidatorUnavailable)
    }

    fn generic_validator_unavailable(
        _message: &TransportMessage,
    ) -> Result<(), TransportDispatchError> {
        Err(TransportDispatchError::ValidatorUnavailable)
    }

    fn definition_validator_unused(
        _message: &TransportMessage,
        _kind: TransportRequestOrNotificationKind,
    ) -> Result<(), TransportDispatchError> {
        Ok(())
    }

    fn injected_frame(value: Value) -> super::DecodedRequestFrame {
        let mut frame = decode_request_frame(value.to_string().as_bytes()).unwrap();
        frame.definition_validator = validator_unavailable;
        frame
    }

    #[test]
    fn validator_unavailable_preempts_normal_policy_and_request_claim() {
        let mut runtime = Runtime::default();
        let frame = injected_frame(json!({
            "jsonrpc": "2.0",
            "id": "health-before-ready",
            "method": "runtime/health",
            "params": {}
        }));
        let mut output = Vec::new();
        runtime.handle_frame_stream(frame, |message| output.push(message));

        assert!(output.is_empty());
        assert!(runtime.should_shutdown());
        assert!(runtime.control.lock().request_ids.is_empty());
    }

    #[test]
    fn generic_validator_unavailable_produces_no_frame_or_peer_response() {
        let error = decode_request_frame_with_validators(
            br#"{"jsonrpc":"2.0","id":"health","method":"runtime/health","params":{}}"#,
            generic_validator_unavailable,
            definition_validator_unused,
        )
        .expect_err("generic validator failure must close ingress");

        assert_eq!(error, RequestFrameError::ValidatorUnavailable);
        assert!(request_frame_error_response(&error).is_none());
    }

    #[test]
    fn validator_unavailable_preempts_out_of_band_readiness_and_capability_gates() {
        for protocol_ready in [false, true] {
            let control = RuntimeControl::default();
            control.set_protocol_ready(protocol_ready);
            let frame = injected_frame(json!({
                "jsonrpc": "2.0",
                "id": if protocol_ready { "heartbeat-no-capability" } else { "heartbeat-before-ready" },
                "method": "runtime/heartbeat",
                "params": {
                    "schema_version": "runtime-heartbeat-request/0.1",
                    "nonce": "validator-failure"
                }
            }));

            assert_eq!(
                control.handle_out_of_band_frame(&frame),
                Err(RequestFrameError::ValidatorUnavailable)
            );
            let state = control.lock();
            assert!(state.request_ids.is_empty());
            assert!(state.active_turn.is_none());
            drop(state);
            assert!(control.terminals.lock().unwrap().records.is_empty());
        }
    }

    #[test]
    fn validator_unavailable_on_dequeued_frame_has_no_runtime_side_effect() {
        let mut runtime = Runtime::default();
        let initialized = runtime.handle_line(
            &json!({
                "jsonrpc": "2.0",
                "id": "initialize",
                "method": "initialize",
                "params": test_initialize_params("validator-failure-test")
            })
            .to_string(),
        );
        assert_eq!(initialized[0]["id"], "initialize");
        assert!(runtime
            .handle_line(r#"{"jsonrpc":"2.0","method":"initialized","params":{}}"#)
            .is_empty());
        let initial_next_id = runtime.next_id;
        let initial_session_count = runtime.sessions.len();
        let initial_request_ids = runtime.control.lock().request_ids.clone();
        let frame = injected_frame(json!({
            "jsonrpc": "2.0",
            "id": "session-start",
            "method": "session/start",
            "params": {"mode": "chat"}
        }));
        let mut output = Vec::new();
        runtime.handle_frame_stream(frame, |message| output.push(message));

        assert!(output.is_empty());
        assert!(runtime.should_shutdown());
        assert_eq!(runtime.next_id, initial_next_id);
        assert_eq!(runtime.sessions.len(), initial_session_count);
        assert_eq!(runtime.control.lock().request_ids, initial_request_ids);
    }
}

#[derive(Default)]
struct TerminalState {
    manager: TerminalManager,
    records: HashMap<String, TerminalRecord>,
}

#[derive(Default)]
struct RuntimeControlState {
    protocol_ready: bool,
    negotiated_capabilities: BTreeSet<String>,
    negotiated_max_frame_bytes: Option<u64>,
    request_ids: HashSet<String>,
    active_turn: Option<ActiveTurnControl>,
}

struct ActiveTurnControl {
    session_id: String,
    turn_id: Option<String>,
    cancellation: TurnCancellationHandle,
    steering: TurnSteeringHandle,
}

#[derive(Clone, Debug, Default)]
pub(crate) struct TurnCancellationHandle {
    requested: Arc<AtomicBool>,
}

impl TurnCancellationHandle {
    pub(crate) fn is_requested(&self) -> bool {
        self.requested.load(Ordering::Acquire)
    }

    fn request(&self) -> bool {
        self.requested.swap(true, Ordering::AcqRel)
    }
}

const TURN_STEER_QUEUE_CAPACITY: usize = 8;
const MAX_TURN_STEER_INPUT_BYTES: usize = 64 * 1024;
const MAX_CLIENT_USER_MESSAGE_ID_BYTES: usize = 256;

#[derive(Debug, Clone)]
pub(crate) struct TurnSteerRequest {
    pub input: String,
    pub client_user_message_id: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub(crate) struct TurnSteeringHandle {
    pending: Arc<Mutex<VecDeque<TurnSteerRequest>>>,
}

impl TurnSteeringHandle {
    pub(crate) fn drain(&self) -> Vec<TurnSteerRequest> {
        let mut pending = self
            .pending
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        pending.drain(..).collect()
    }

    fn enqueue(&self, request: TurnSteerRequest) -> Result<usize, ()> {
        let mut pending = self
            .pending
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if pending.len() >= TURN_STEER_QUEUE_CAPACITY {
            return Err(());
        }
        pending.push_back(request);
        Ok(pending.len())
    }
}

#[derive(Debug, Deserialize)]
struct TurnCancelParams {
    session_id: String,
    turn_id: String,
}

#[derive(Debug, Deserialize)]
struct TurnSteerParams {
    session_id: String,
    turn_id: String,
    input: String,
    #[serde(default)]
    client_user_message_id: Option<String>,
}

impl RuntimeControl {
    fn lock(&self) -> MutexGuard<'_, RuntimeControlState> {
        self.state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    fn claim_request(&self, request: &Request) -> Option<Value> {
        let id = request.id.as_ref()?;
        let mut state = self.lock();
        if state.request_ids.insert(id.to_string()) {
            None
        } else {
            Some(
                serde_json::to_value(Response::error(id.clone(), -32001, "duplicate request id"))
                    .expect("duplicate request response serialization"),
            )
        }
    }

    fn set_protocol_ready(&self, ready: bool) {
        self.lock().protocol_ready = ready;
    }

    fn set_negotiated_contract(&self, capabilities: &BTreeSet<String>, max_frame_bytes: u64) {
        let mut state = self.lock();
        state.negotiated_capabilities = capabilities.clone();
        state.negotiated_max_frame_bytes = Some(max_frame_bytes);
    }

    pub fn reject_oversized_line(&self, line: &str) -> Option<Vec<Value>> {
        self.reject_oversized_frame_bytes(line.len())
    }

    pub fn reject_oversized_frame(&self, frame: &DecodedRequestFrame) -> Option<Vec<Value>> {
        self.reject_oversized_frame_bytes(frame.byte_len())
    }

    fn reject_oversized_frame_bytes(&self, byte_len: usize) -> Option<Vec<Value>> {
        let limit = self
            .lock()
            .negotiated_max_frame_bytes
            .unwrap_or(MAX_AAP_FRAME_BYTES);
        if u64::try_from(byte_len).unwrap_or(u64::MAX) <= limit {
            return None;
        }
        Some(vec![oversized_frame_response()])
    }

    pub fn overload_response(&self, line: &str) -> Option<Value> {
        match decode_request_frame(line.as_bytes()) {
            Ok(frame) => self.overload_response_frame(&frame),
            Err(error) => request_frame_error_response(&error),
        }
    }

    pub fn overload_response_frame(&self, frame: &DecodedRequestFrame) -> Option<Value> {
        let request = frame.request();
        let id = request.id.clone()?;
        Some(
            serde_json::to_value(Response::error(id, -32004, "AAP request queue is full"))
                .expect("overload response serialization"),
        )
    }

    fn begin_turn(&self, session_id: &str) -> TurnCancellationHandle {
        let cancellation = TurnCancellationHandle::default();
        self.lock().active_turn = Some(ActiveTurnControl {
            session_id: session_id.into(),
            turn_id: None,
            cancellation: cancellation.clone(),
            steering: TurnSteeringHandle::default(),
        });
        cancellation
    }

    fn steering_handle(&self, session_id: &str) -> Option<TurnSteeringHandle> {
        self.lock()
            .active_turn
            .as_ref()
            .filter(|active| active.session_id == session_id)
            .map(|active| active.steering.clone())
    }

    fn identify_turn(&self, session_id: &str, turn_id: &str) {
        let mut state = self.lock();
        if let Some(active) = state.active_turn.as_mut() {
            if active.session_id == session_id {
                active.turn_id = Some(turn_id.into());
            }
        }
    }

    fn has_active_turn(&self, session_id: &str) -> bool {
        self.lock()
            .active_turn
            .as_ref()
            .is_some_and(|active| active.session_id == session_id)
    }

    fn request_active_turn_cancellation(&self) {
        if let Some(active) = self.lock().active_turn.as_ref() {
            active.cancellation.request();
        }
    }

    fn protected_session_ids(&self) -> BTreeSet<String> {
        let mut protected = BTreeSet::new();
        if let Some(active) = self.lock().active_turn.as_ref() {
            protected.insert(active.session_id.clone());
        }
        let terminals = self
            .terminals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        protected.extend(
            terminals
                .records
                .values()
                .filter(|terminal| matches!(terminal.state.as_str(), "running" | "stopping"))
                .map(|terminal| terminal.session_id.clone()),
        );
        protected
    }

    fn has_active_work(&self) -> bool {
        let state = self.lock();
        if state.active_turn.is_some() {
            return true;
        }
        drop(state);
        self.terminals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .records
            .values()
            .any(|terminal| matches!(terminal.state.as_str(), "running" | "stopping"))
    }

    fn finish_turn(&self, session_id: &str) {
        let mut state = self.lock();
        if state
            .active_turn
            .as_ref()
            .is_some_and(|active| active.session_id == session_id)
        {
            state.active_turn = None;
        }
    }

    fn cancel_claimed(&self, request: Request) -> Vec<Value> {
        if !self.lock().protocol_ready {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32002,
                "initialize handshake required",
            ))
            .expect("cancel readiness response serialization")];
        }
        let params: TurnCancelParams = match serde_json::from_value(request.params) {
            Ok(params) => params,
            Err(error) => {
                return vec![serde_json::to_value(Response::error(
                    request.id.unwrap_or(Value::Null),
                    -32602,
                    format!("invalid params: {error}"),
                ))
                .expect("cancel parameter response serialization")]
            }
        };
        if params.session_id.is_empty() || params.turn_id.is_empty() {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32602,
                "session_id and turn_id must not be empty",
            ))
            .expect("cancel validation response serialization")];
        }
        let mut state = self.lock();
        let Some(active) = state.active_turn.as_mut() else {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32080,
                "turn is not active",
            ))
            .expect("inactive turn response serialization")];
        };
        if active.session_id != params.session_id
            || active.turn_id.as_deref() != Some(params.turn_id.as_str())
        {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32081,
                "turn identity does not match the active turn",
            ))
            .expect("turn identity response serialization")];
        }
        let already_requested = active.cancellation.requested.swap(true, Ordering::AcqRel);
        vec![serde_json::to_value(Response::success(
            request.id.unwrap_or(Value::Null),
            json!({
                "session_id": params.session_id,
                "turn_id": params.turn_id,
                "state": "cancellation-requested",
                "already_requested": already_requested
            }),
        ))
        .expect("cancel response serialization")]
    }

    fn steer_claimed(&self, request: Request) -> Vec<Value> {
        if !self.lock().protocol_ready {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32002,
                "initialize handshake required",
            ))
            .expect("steer readiness response serialization")];
        }
        let params: TurnSteerParams = match serde_json::from_value(request.params) {
            Ok(params) => params,
            Err(error) => {
                return vec![serde_json::to_value(Response::error(
                    request.id.unwrap_or(Value::Null),
                    -32602,
                    format!("invalid params: {error}"),
                ))
                .expect("steer parameter response serialization")]
            }
        };
        if params.session_id.is_empty()
            || params.turn_id.is_empty()
            || params.input.trim().is_empty()
        {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32602,
                "session_id, turn_id, and input must not be empty",
            ))
            .expect("steer validation response serialization")];
        }
        if params.input.len() > MAX_TURN_STEER_INPUT_BYTES {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32602,
                "turn steering input exceeds the 64 KiB limit",
            ))
            .expect("steer input limit response serialization")];
        }
        if params.client_user_message_id.as_ref().is_some_and(|id| {
            id.is_empty()
                || id.len() > MAX_CLIENT_USER_MESSAGE_ID_BYTES
                || id.chars().any(char::is_control)
        }) {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32602,
                "client_user_message_id is invalid",
            ))
            .expect("steer client message id response serialization")];
        }

        let mut state = self.lock();
        let Some(active) = state.active_turn.as_mut() else {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32080,
                "turn is not active",
            ))
            .expect("inactive steer response serialization")];
        };
        if active.session_id != params.session_id
            || active.turn_id.as_deref() != Some(params.turn_id.as_str())
        {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32081,
                "turn identity does not match the active turn",
            ))
            .expect("steer identity response serialization")];
        }
        let queued = match active.steering.enqueue(TurnSteerRequest {
            input: params.input,
            client_user_message_id: params.client_user_message_id,
        }) {
            Ok(queued) => queued,
            Err(()) => {
                return vec![serde_json::to_value(Response::error(
                    request.id.unwrap_or(Value::Null),
                    -32004,
                    "turn steering queue is full",
                ))
                .expect("steer queue response serialization")]
            }
        };
        vec![serde_json::to_value(Response::success(
            request.id.unwrap_or(Value::Null),
            json!({
                "session_id": params.session_id,
                "turn_id": params.turn_id,
                "state": "steering-requested",
                "queued": queued
            }),
        ))
        .expect("steer response serialization")]
    }

    fn terminal_stop_claimed(&self, request: Request) -> Vec<Value> {
        if !self.lock().protocol_ready {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32002,
                "initialize handshake required",
            ))
            .expect("terminal stop readiness response serialization")];
        }
        let params: TerminalReadParams = match serde_json::from_value(request.params) {
            Ok(params) => params,
            Err(error) => {
                return vec![serde_json::to_value(Response::error(
                    request.id.unwrap_or(Value::Null),
                    -32602,
                    format!("invalid params: {error}"),
                ))
                .expect("terminal stop parameter response serialization")]
            }
        };
        let mut terminals = self
            .terminals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match terminals.stop_user(&params.terminal_id, &params.session_id) {
            Ok(snapshot) => vec![serde_json::to_value(Response::success(
                request.id.unwrap_or(Value::Null),
                snapshot,
            ))
            .expect("terminal stop response serialization")],
            Err(error) => vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                error.code,
                error.message,
            ))
            .expect("terminal stop error serialization")],
        }
    }

    fn heartbeat_claimed(&self, request: Request) -> Vec<Value> {
        if !self.lock().protocol_ready {
            return vec![serde_json::to_value(Response::error(
                request.id.unwrap_or(Value::Null),
                -32002,
                "initialize handshake required",
            ))
            .expect("heartbeat readiness response serialization")];
        }
        let params: RuntimeHeartbeatParams = match serde_json::from_value(request.params) {
            Ok(params) => params,
            Err(_) => {
                return vec![serde_json::to_value(Response::error(
                    request.id.unwrap_or(Value::Null),
                    -32602,
                    "runtime heartbeat params are invalid",
                ))
                .expect("heartbeat parameter response serialization")]
            }
        };
        let result = RuntimeHeartbeatResult {
            schema_version: "runtime-heartbeat/0.1".into(),
            nonce: params.nonce,
            state: "alive".into(),
        };
        vec![serde_json::to_value(Response::success(
            request.id.unwrap_or(Value::Null),
            serde_json::to_value(result).expect("heartbeat result serialization"),
        ))
        .expect("heartbeat response serialization")]
    }

    pub fn handle_out_of_band_line(
        &self,
        line: &str,
    ) -> Result<Option<Vec<Value>>, RequestFrameError> {
        if let Some(response) = self.reject_oversized_line(line) {
            return Ok(Some(response));
        }
        match decode_request_frame(line.as_bytes()) {
            Ok(frame) => self.handle_out_of_band_frame(&frame),
            Err(RequestFrameError::ValidatorUnavailable) => {
                Err(RequestFrameError::ValidatorUnavailable)
            }
            Err(error) => Ok(request_frame_error_response(&error).map(|response| vec![response])),
        }
    }

    pub fn handle_out_of_band_frame(
        &self,
        frame: &DecodedRequestFrame,
    ) -> Result<Option<Vec<Value>>, RequestFrameError> {
        let method = frame.request().method.as_str();
        if !matches!(
            method,
            "runtime/heartbeat" | "turn/cancel" | "turn/steer" | "terminal/stop-user"
        ) {
            return Ok(None);
        }
        frame.prove_definition_validator_available()?;
        let Some(_) = frame.request().id.as_ref() else {
            if method == "runtime/heartbeat" {
                return Ok(Some(vec![serde_json::to_value(Response::error(
                    Value::Null,
                    -32600,
                    "runtime heartbeat must be a request",
                ))
                .expect("heartbeat notification response serialization")]));
            }
            return Ok(Some(Vec::new()));
        };
        let request = frame.request().clone();
        if let Err(error) = frame.validate_known_kind() {
            return match error {
                TransportDispatchError::InvalidEnvelope => {
                    Ok(Some(vec![serde_json::to_value(Response::error(
                        request.id.clone().unwrap_or(Value::Null),
                        -32600,
                        "known AAP request or notification kind is invalid",
                    ))
                    .expect("out-of-band known kind response serialization")]))
                }
                TransportDispatchError::ValidatorUnavailable => {
                    Err(RequestFrameError::ValidatorUnavailable)
                }
                _ => Err(RequestFrameError::ValidatorUnavailable),
            };
        }
        let required = match request.method.as_str() {
            "runtime/heartbeat" => vec!["runtime.heartbeat.out-of-band"],
            "turn/cancel" => vec!["turn.cancel.interrupt"],
            "turn/steer" => vec!["turn.steer.same-turn"],
            "terminal/stop-user" => vec![
                "terminal.lifecycle.named",
                TerminalManager::capability(),
                "terminal.stop.out-of-band",
            ],
            _ => unreachable!("out-of-band method was checked above"),
        };
        let state = self.lock();
        if !state.protocol_ready {
            drop(state);
            // The initialized notification is consumed by the ordered runtime
            // dispatcher. Queue an out-of-band request until that transition is
            // visible so a heartbeat cannot overtake the handshake.
            return Ok(None);
        }
        if required
            .iter()
            .any(|capability| !state.negotiated_capabilities.contains(*capability))
        {
            drop(state);
            return Ok(Some(vec![serde_json::to_value(Response::error(
                request
                    .id
                    .clone()
                    .expect("out-of-band requests require IDs"),
                -32006,
                "required capability was not negotiated",
            ))
            .expect("out-of-band capability response serialization")]));
        }
        drop(state);
        if let Some(duplicate) = self.claim_request(&request) {
            return Ok(Some(vec![duplicate]));
        }
        Ok(Some(match request.method.as_str() {
            "runtime/heartbeat" => self.heartbeat_claimed(request),
            "turn/cancel" => self.cancel_claimed(request),
            "turn/steer" => self.steer_claimed(request),
            "terminal/stop-user" => self.terminal_stop_claimed(request),
            _ => unreachable!("out-of-band method was checked above"),
        }))
    }
}

