fn contains_case_insensitive(haystack: &str, needle: &str) -> bool {
    haystack
        .to_ascii_lowercase()
        .contains(&needle.to_ascii_lowercase())
}

const fn default_repository_map_tokens() -> usize {
    2_048
}

const fn default_include_stale() -> bool {
    true
}

